/* Public city listings only. Personal history, Gmail and calendar contents never leave the browser. */
(function(root){'use strict';
const base='https://comealone.app/feed/v1/',maxAge=48*3600000;
function safeUrl(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&u.hostname.includes('.')&&!/^\d+(?:\.\d+){3}$/.test(u.hostname)&&!/(?:^|\.)(?:localhost|local|internal)$/.test(u.hostname)?u.href:null;}catch{return null;}}
function normalize(raw,{now=Date.now(),readAt=new Date(now).toISOString(),citySlug}={}){if(!raw||typeof raw.id!=='string'||typeof raw.title!=='string'||raw.city_slug!==citySlug||!/(?:Z|[+-]\d\d:\d\d)$/.test(raw.start||'')||!/(?:Z|[+-]\d\d:\d\d)$/.test(raw.end||''))return null;const valid=s=>{const [y,m,d]=s.slice(0,10).split('-').map(Number);return y>=2000&&m>=1&&m<=12&&d>=1&&d<=new Date(Date.UTC(y,m,0)).getUTCDate();};if(!valid(raw.start)||!valid(raw.end))return null;const start=Date.parse(raw.start),end=Date.parse(raw.end),url=safeUrl(raw.source_url);if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start||start<=now||start-now>31*86400000||!url)return null;
 return {id:'public:'+raw.id.slice(0,200),title:raw.title.trim().slice(0,160),description:typeof raw.description==='string'?raw.description.slice(0,600):'',eventStart:start,eventEnd:end,city:String(raw.city||'').slice(0,100),venue:String(raw.venue||'').slice(0,160),timezone:String(raw.timezone||''),price:String(raw.price||'Price unknown').slice(0,160),isFree:raw.is_free===true,url,readAt,attribution:'Come Alone / Meet & Mint · CC BY 4.0'};
}
async function get(path){const control=new AbortController(),timer=setTimeout(()=>control.abort(),20000);try{const response=await fetch(base+path,{credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store',signal:control.signal});if(!response.ok)throw Error('Public discovery returned '+response.status+'.');const text=await response.text();if(text.length>3000000)throw Error('Public discovery response is too large.');return JSON.parse(text);}finally{clearTimeout(timer);}}
function fresh(meta){const time=Date.parse(meta?.generated_at);if(!Number.isFinite(time)||Date.now()-time>maxAge||time-Date.now()>3600000)throw Error('This public feed is stale or has an invalid timestamp. It is not used for recommendations.');}
async function cities(){const data=await get('cities.json');fresh(data.meta);if(!Array.isArray(data.cities))throw Error('Public city directory has an unsupported format.');return data.cities.filter(c=>typeof c.slug==='string'&&/^[a-z0-9-]{1,100}$/.test(c.slug)&&typeof c.city==='string').map(c=>({slug:c.slug,title:c.city+(c.country?' · '+c.country:''),count:Number(c.count)||0})).sort((a,b)=>a.title.localeCompare(b.title));}
async function events(slug){if(!/^[a-z0-9-]{1,100}$/.test(slug))throw Error('Select a city from the directory.');const data=await get('city/'+slug+'.json');fresh(data.meta);if(!Array.isArray(data.events))throw Error('Public event feed has an unsupported format.');const readAt=new Date().toISOString();return {generatedAt:data.meta.generated_at,readAt,events:data.events.slice(0,1000).map(e=>normalize(e,{citySlug:slug,readAt})).filter(Boolean).slice(0,100)};}
function displayTime(e){try{return new Date(e.eventStart).toLocaleString(undefined,{timeZone:e.timezone||'UTC'})+' ('+(e.timezone||'UTC')+')';}catch{return new Date(e.eventStart).toISOString();}}
function candidate(e){return {id:e.id,title:('Look into: '+e.title).slice(0,160),description:e.description,source:'discovery',category:'discovery',minutes:10,effort:1,money:0,fixedStart:null,deadline:e.eventStart,listing:e,provenance:{provider:'public-discovery',id:e.id,title:e.title,readAt:e.readAt,url:e.url},assumptions:'A 10-minute idea to investigate, not a booking or a claim you can attend. The listed event has its own time, price and eligibility; check its official page, travel and availability. Investigating assumes internet access you already have.'};}
const api={safeUrl,normalize,cities,events,candidate,displayTime};if(typeof module==='object'&&module.exports)module.exports=api;root.WamPublicDiscovery=api;
})(typeof globalThis!=='undefined'?globalThis:this);
